// --- Pimpl with std::unique_ptr (requires special members) ---
// In header:
class UniquePimplWidget {
public:
    UniquePimplWidget();
    ~UniquePimplWidget(); // Must be declared
private:
    struct Impl; 
    std::unique_ptr<Impl> pImpl; // Deleter type is part of std::unique_ptr<Impl>'s type
};
// In .cpp, ~UniquePimplWidget() must be defined where Impl is complete.
// Compiling code that destroys UniquePimplWidget requires Impl's full definition.

// --- Pimpl with std::shared_ptr (simpler, no special members needed) ---
// In header:
class SharedPimplWidget {
public:
    SharedPimplWidget();
    // ~SharedPimplWidget(); // No need to declare dtor
private:
    struct Impl;
    std::shared_ptr<Impl> pImpl; // Deleter is in a control block, not part of the type
};
// In .cpp:
// SharedPimplWidget::~SharedPimplWidget() {} // Definition is not required.
// The compiler-generated destructor is sufficient because destroying a
// std::shared_ptr to an incomplete type is a valid operation.
